"""Local visual review of authored models, source references, and traversal audit."""
import json, html, re
from pathlib import Path
P=Path(__file__).resolve().parents[2];B=P/'build/highrises';R=B/'review';e=html.escape
plans=json.loads((B/'plan.json').read_text());refs=json.loads((B/'references/search.json').read_text());guest=json.loads((B/'references/guest-search.json').read_text())
rooms=json.loads((B/'references/room-search.json').read_text())
print('Reference collections',type(guest).__name__,type(rooms).__name__)
alias={'bellagio-spa':'Bellagio','wynn':'Wynn Encore','encore':'Wynn Encore','venetian':'Venetian Palazzo','palazzo':'Venetian Palazzo','new-york':'New York New York','harrahs':'Harrahs','signature':'Signature MGM','trump':'Trump','sahara':'Sahara','strat':'Strat','grand-chateau':'Marriott Grand Chateau','springhill':'SpringHill Suites Convention Center','hgv-boulevard':'Hilton Grand Vacations Boulevard'}
def ref_key(p):
 if p['key'] in alias:return alias[p['key']]
 for n in refs:
  if n.lower()==p['name'].lower().replace('the ',''):return n
 return p['reference']
def link(r):
 s=r.get('source','');m=re.search(r'\((https?://[^\s]+)\)\s*$',s)
 return m.group(1) if m else r.get('url',r.get('image',''))
rows=[];cards=[]
for p in plans:
 towers=p['towers'];heights=[f['height'] for f in p['features']];key=ref_key(p);rr=refs.get(key,[])
 links=' · '.join(f'<a href="{e(link(r))}" target="_blank">Photo {i+1}</a>' for i,r in enumerate(rr))
 if not links and p['key']=='bellagio-spa':links='<a href="https://bellagio.mgmresorts.com/en/hotel.html">Bellagio rooms</a>'
 count=sum((t['floors']-t['firstGuestFloor'])*t['bays']*2 for t in towers)
 rows.append(f'<tr><td><a href="http://localhost:3090/?hotelDebug=1&amp;hotel={towers[0]["id"]}">{e(p["name"])}</a></td><td>{min(heights):.0f}–{max(heights):.0f} m</td><td>{len(p["ids"])}</td><td>{len(towers)}</td><td>{count:,}</td><td>{links}</td></tr>')
 sample=next((B/'references'/(key.replace(' ','-')+f'-{i}.jpg') for i in range(3) if (B/'references'/(key.replace(' ','-')+f'-{i}.jpg')).exists()),None)
 if sample:cards.append(f'<figure><a href="{e(link(rr[0]))}"><img loading="lazy" src="../references/{e(sample.name)}"></a><figcaption>{e(p["name"])} · online reference</figcaption></figure>')
examples=[]
for key,label in [('wynn','Wynn'),('new-york','New York New York'),('turnberry-place','Turnberry Place'),('luxor','Luxor')]:
 ims=''.join(f'<figure><a href="{key}-{suffix}.png"><img loading="lazy" src="{key}-{suffix}.png"></a><figcaption>{e(caption)} · authored asset render</figcaption></figure>' for suffix,caption in [('exterior','Exterior massing and facade'),('1-lobby','Entrance lobby'),('corridor','Guest corridor'),('room','Guest room / residence')])
 examples.append(f'<section><h2>{label}</h2><div class="grid">{ims}</div></section>')
proof=''.join(f'<figure><a href="{p.name}"><img loading="lazy" src="{p.name}"></a><figcaption>{e(p.stem.replace("-"," "))} · actual WebGPU game</figcaption></figure>' for p in sorted(R.glob('*-game.jpg')))
report='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Vegas · High-rise reconstruction review</title><style>body{margin:0;background:#10191c;color:#e4e7e3;font:16px/1.55 system-ui}main{max-width:1400px;margin:auto;padding:40px}h1{font-size:42px;line-height:1.1}h2{margin-top:48px}p{max-width:1000px;color:#bfcac7}a{color:#a8dece}small{color:#b8bfbb}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0;background:#1b292d;border:1px solid #344348}img{display:block;width:100%;height:360px;object-fit:contain;background:#0b1013}figcaption{padding:14px}.references img{height:230px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid #344348}th{color:#a8dece}.table{overflow:auto}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats b{font-size:32px;display:block}.stats div{padding:18px 24px;background:#1b292d}details{margin-top:30px}summary{cursor:pointer;font-size:22px}@media(max-width:750px){.grid{grid-template-columns:1fr}main{padding:20px}img{height:auto}}</style><main><small>LOCAL PROTOTYPE · 4 OCTOBER 2026</small><h1>Mapped towers, reachable interiors</h1><p>35 property groups now replace 77 plain OSM building records. Their footprint and height remain the map's authority. Facades, colors, window patterns and interior finishes use photographic references. Entrances connect to furnished lobbies, stairs, guest corridors and rooms through the existing streaming system.</p><div class="stats"><div><b>35</b>property sets</div><div><b>47</b>guest cores</div><div><b>30,588</b>virtual room identities</div><div><b>37,913</b>route checks passed</div></div><p>The interior layouts are fitted game adaptations, not measured replicas of real floor plans; apartment decor varies between individual residences. Mirage uses its recognizable Mirage-era appearance. Room counts above describe generated game capacity, not actual resort inventory. Preview renders below show the authored geometry under neutral lighting; screenshots marked “actual WebGPU game” show runtime appearance.</p><h2>In the game</h2><div class="grid">'''+proof+'''</div>'''+''.join(examples)+'''<h2>Coverage and source photographs</h2><p>Click a property to open its local review controls. PLAY, choose that resort in the review selector, and use Inspect entrance, lobby, hallway or room. The height column shows the range among replaced map parts, including podiums where present.</p><div class="table"><table><thead><tr><th>Property</th><th>Map height</th><th>Source records</th><th>Guest cores</th><th>Virtual rooms</th><th>References</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><details><summary>Exterior reference contact sheet</summary><div class="grid references">'''+''.join(cards)+'''</div></details><details><summary>Guest reference contact sheets</summary><p>Research contact sheets include search candidates; incorrect destinations and unrelated rooms were excluded from the implemented design. Source search records are linked below for traceability.</p><div class="grid references">'''+''.join(f'<figure><a href="../references/{p.name}"><img loading="lazy" src="../references/{p.name}"></a><figcaption>{e(p.stem)}</figcaption></figure>' for p in sorted((B/'references').glob('*contact-*.jpg')) if not p.name.startswith('contact-') and p.name!='room-contact-3.jpg')+'''</div></details><p><a href="../route-audit.json">Collision and route audit</a> · <a href="../references/search.json">Exterior sources</a> · <a href="../references/guest-search.json">Lobby and corridor sources</a> · <a href="../references/room-search.json">Room sources</a> · <a href="../verify-result.json">Engine verification</a></p><p>Detailed facade pieces are culled beyond 950 m; silhouette shells remain visible. Ground-level collision loads nearby. Hotel lobbies, stairs, corridors and rooms load on approach or entry, and inactive sets are evicted. Old source boxes are removed rather than drawn behind the new shells.</p></main></html>'''
(R/'index.html').write_text(report)
print(R/'index.html')
